import math
from itertools import product

def is_prime(n):
    """Checks if a positive integer n is prime."""
    if n is None or not isinstance(n, int) or n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def calculate_P(x, y, z):
    """Calculates P = y^x * z^y * x^z, handling potential non-integer/negative results."""
    try:
        p1 = y**x
        p2 = z**y
        p3 = x**z
        P = p1 * p2 * p3

        if isinstance(P, float) and P.is_integer():
            P = int(P)

        return P
    except OverflowError:
        return None
    except ValueError:
        return None

def find_good_triples(max_s):
    """Searches for good triples up to a maximum sum of squares S."""
    good_triples = set()

    max_coord = int(math.sqrt(max_s)) + 1 

    search_range = range(-max_coord, max_coord + 1)
    search_range = [c for c in search_range if c != 0]

    # print(f"Searching triples (x, y, z) where |x|,|y|,|z| <= {max_coord}...")

    for x, y, z in product(search_range, repeat=3):
        S = x*x + y*y + z*z
        if S > max_s:
            continue

        P = calculate_P(x, y, z)

        if P is not None and P > 0 and is_prime(P):
            # Store (S, x, y, z) for sorting
            good_triples.add((S, x, y, z))

    sorted_triples = sorted(list(good_triples))

    return sorted_triples

# Increasing MAX_S to 400 to ensure we capture at least 50 triples, 
# including the q=17 family (S=291) and possibly q=19 family (S=363) if we were unlucky with the bounds.
MAX_S = 400 
results = find_good_triples(MAX_S)

if len(results) >= 50:
    print(f"Successfully found {len(results)} triples.")
    top_50 = results[:50]
    print("\n--- Top 50 Good Triples (S, x, y, z) ---")
    for i, (S, x, y, z) in enumerate(top_50):
        print(f"{i+1:2}. S={S:3d}: ({x}, {y}, {z})")
else:
    print(f"Failed to find 50 triples. Only found {len(results)}.")
